/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
-    always @(posedge clk or negedge rst_n) begin
-        if ("'!rst_n)
-            clk_out7 <= 1'"'b0;
-        else
-            clk_out7 <= clkp | clkn;
-    end
+   assign clk_out7 = clkp | clkn;
 endmodule
*** End Patch
PATCH

cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk_in = 0;
  reg rst = 0;
  wire clk_out7;

  TopModule dut (
    .rst(rst),
    .clk_in(clk_in),
    .clk_out7(clk_out7)
  );

  always #5 clk_in = ~clk_in;

  integer rise_count = 0;
  integer out_toggle_count = 0;
  reg last_out;
  time last_toggle_time;

  initial begin
    last_out = clk_out7;
    last_toggle_time = 0;
    #12;
    rst = 1;
    repeat (30) begin
      @(posedge clk_in);
      rise_count = rise_count + 1;
    end
    $finish;
  end

  always @(clk_out7) begin
    if (rst && clk_out7 !== last_out) begin
      out_toggle_count = out_toggle_count + 1;
      $display("toggle %0d at t=%0t out=%0b", out_toggle_count, $time, clk_out7);
      if (last_toggle_time != 0)
        $display("  half-period=%0t", $time - last_toggle_time);
      last_toggle_time = $time;
      last_out = clk_out7;
    end
  end
endmodule
EOF

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

